 * <p>
 * Pelo contrato, {@code email}, {@code username} e {@code password} não aceitam {@code null}: um {@code null}
 * explícito é rejeitado com 422. Já {@code bio} e {@code image} aceitam {@code null}, que remove o valor atual;
 * por isso o {@code null} explícito é convertido em texto vazio, que o serviço interpreta como remoção.
 */
public record UpdateUser(
        @JsonSetter(nulls = Nulls.FAIL)
        @Pattern(regexp = ValidationMessages.NOT_BLANK_REGEX, message = ValidationMessages.BLANK)
        @Email(message = ValidationMessages.INVALID)
        @Size(max = 254, message = ValidationMessages.TOO_LONG)
        String email,

        @JsonSetter(nulls = Nulls.FAIL)
        @Pattern(regexp = ValidationMessages.NOT_BLANK_REGEX, message = ValidationMessages.BLANK)
