        String username,

        @JsonSetter(nulls = Nulls.FAIL)
        @Pattern(regexp = ValidationMessages.NOT_BLANK_REGEX, message = ValidationMessages.BLANK)
        String password,

        @JsonSetter(nulls = Nulls.AS_EMPTY)
        String bio,

        @JsonSetter(nulls = Nulls.AS_EMPTY)
        @Size(max = 2048, message = ValidationMessages.TOO_LONG)
        String image) {
}

